diff --git a/zjit/src/hir.rs b/zjit/src/hir.rs
index 7875e13179..245928f77f 100644
--- a/zjit/src/hir.rs
+++ b/zjit/src/hir.rs
@@ -3093,6 +3093,30 @@ impl SendDirectFailure {
         for &counter in &self.counters {
             function.count(block, counter);
         }
+        if self.counters.contains(&Counter::complex_arg_pass_param_kwrest) {
+            let cd = match function.insns[send_insn] {
+                Insn::Send { cd, .. } | Insn::InvokeSuper { cd, .. } => cd,
+                _ => unreachable!(),
+            };
+            let ci = unsafe { (*cd).ci };
+            let mid = unsafe { vm_ci_mid(ci) };
+            let counter = match mid.contents_lossy().as_ref() {
+                "form_with" => Counter::betz_kwrest_form_with,
+                "token_tag" => Counter::betz_kwrest_token_tag,
+                "tag" | "tag_options" | "tag_option" | "content_tag" | "link" | "script" | "meta" | "dialog" | "title" => Counter::betz_kwrest_tag_helpers,
+                "url_for" => Counter::betz_kwrest_url_for,
+                "render" | "render_to_string" => Counter::betz_kwrest_render,
+                "capture" => Counter::betz_kwrest_capture,
+                _ => Counter::betz_kwrest_other,
+            };
+            function.count(block, counter);
+            if self.counters.len() == 1 {
+                function.count(block, Counter::betz_kwrest_only);
+            }
+            function.count(block, if unsafe { rb_vm_ci_flag(ci) } & VM_CALL_KWARG != 0 {
+                Counter::betz_kwrest_explicit_keywords
+            } else { Counter::betz_kwrest_no_keywords });
+        }
         let context_counter = match context {
             SendDirectFallbackContext::Send => Counter::send_direct_fallback_context_send,
             SendDirectFallbackContext::Super => Counter::send_direct_fallback_context_super,
